#!/usr/bin/env php
<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';$db=Database::connection();$limit=max(1,min(100,(int)($argv[1]??25)));$q=$db->prepare('SELECT * FROM notification_deliveries WHERE status="queued" AND (next_attempt_at IS NULL OR next_attempt_at<=NOW()) ORDER BY created_at LIMIT '.$limit);$q->execute();$processed=0;foreach($q->fetchAll() as $delivery){if($delivery['channel']==='in_app'){$db->prepare('UPDATE notification_deliveries SET status="sent",attempts=attempts+1,sent_at=NOW() WHERE id=?')->execute([$delivery['id']]);$processed++;continue;}$transport=Config::get($delivery['channel']==='email'?'MAIL_TRANSPORT':'PUSH_TRANSPORT','');if(!$transport)continue;$db->prepare('UPDATE notification_deliveries SET status="failed",attempts=attempts+1,failure_message=?,next_attempt_at=DATE_ADD(NOW(),INTERVAL 15 MINUTE) WHERE id=?')->execute(['Configured transport adapter is not installed.',$delivery['id']]);$processed++;}fwrite(STDOUT,"Processed {$processed} delivery jobs.\n");
